#include "protocol/stream_parser.h"
#include <stddef.h>
static void reset(stream_parser_t *p){p->state=PARSER_WAIT_SOF;p->index=0U;p->expected_total=0U;}
void stream_parser_init(stream_parser_t *p){if(!p)return;p->frames_ok=p->crc_errors=p->length_errors=p->resync_count=0U;reset(p);}
bool stream_parser_feed_byte(stream_parser_t *p,uint8_t byte,protocol_frame_t *out){if(!p||!out)return false;if(p->state==PARSER_WAIT_SOF){if(byte==PROTOCOL_SOF){p->buffer[0]=byte;p->index=1U;p->state=PARSER_READ_HEADER;}return false;}if(p->index>=PROTOCOL_MAX_FRAME_SIZE){p->length_errors++;reset(p);return false;}p->buffer[p->index++]=byte;if(p->state==PARSER_READ_HEADER&&p->index==PROTOCOL_HEADER_SIZE){uint8_t n=p->buffer[3];if(n>PROTOCOL_MAX_PAYLOAD){p->length_errors++;reset(p);return false;}p->expected_total=PROTOCOL_HEADER_SIZE+n+PROTOCOL_CRC_SIZE;p->state=n?PARSER_READ_PAYLOAD:PARSER_READ_CRC;}if(p->state==PARSER_READ_PAYLOAD&&p->index==p->expected_total-PROTOCOL_CRC_SIZE)p->state=PARSER_READ_CRC;if(p->state==PARSER_READ_CRC&&p->index==p->expected_total){bool ok=protocol_frame_decode(p->buffer,p->expected_total,out);if(ok)p->frames_ok++;else p->crc_errors++;reset(p);return ok;}return false;}
size_t stream_parser_feed(stream_parser_t *p,const uint8_t *d,size_t l,protocol_frame_t *f,size_t cap){if(!p||!d||!f)return 0U;size_t n=0U;for(size_t i=0;i<l;++i){protocol_frame_t x;if(stream_parser_feed_byte(p,d[i],&x)&&n<cap)f[n++]=x;}return n;}
